param([Parameter(Mandatory)][ValidateSet('BASELINE','REMEDIATION')][string]$Condition,[Parameter(Mandatory)][ValidateSet('001','002','003')][string]$RunIndex,[string]$RunDate='PLAN-DATE',[ValidateSet('PLAN','EXECUTE')][string]$ExecutionMode='PLAN')
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;. (Join-Path $PSScriptRoot 'experiment-1-20-artifact-contract.ps1')
$app='doeng-flux-exp119-fresh-first-20260803:latest';$appId='sha256:c2878d2847f80f3396a5cee5f02f1ec1ca3f7c14ceb8f49ea610d6e5fb6d9168';$mock='doeng-exp119-mock-frozen-20260803:latest';$mockId='sha256:2492f942c3931aa607293cf3da940e0e5aac0cfae91cbfe0ea88a893f0829ac1'
$id="RUN-$RunDate-EXP120-$Condition-$RunIndex";$warm="SMOKE-$RunDate-EXP120-$Condition-$RunIndex";$result=Join-Path $root 'backend\experiments\results\experiment-1-20';$target=Join-Path $result "core\$id";$staging=Join-Path $result "collector-staging\$id";$legacy=Join-Path $root "experiment\results\$id";$plan=Join-Path $result "plan\$Condition-$RunIndex-command-manifest.json"
