function Json($v,$p){New-Item -ItemType Directory -Force -Path (Split-Path $p)|Out-Null;$v|ConvertTo-Json -Depth 12|Set-Content $p -Encoding UTF8}
function ImageId($tag){((& docker image inspect --format '{{.Id}}' $tag).Trim())}
function Gate {if((ImageId $app)-ne$appId -or (ImageId $mock)-ne$mockId){throw 'Frozen image mismatch'};foreach($p in @($target,$legacy,$staging)){if(Test-Path $p){throw "Artifact collision: $p"}}}
$manifest=[ordered]@{experiment='Experiment 1-20';runId=$id;runDate=$RunDate;condition=$Condition;executionMode=$ExecutionMode;applicationImageId=$appId;mockImageTag=$mock;mockImageId=$mockId;mockImageBindingMode='EXPLICIT_FROZEN_TAG';policy=$policy;collector=@{managementUrl='http://127.0.0.1:9001';intervalMilliseconds=1000;durationSeconds=150;stagingPath=$staging;finalPaths=@('pool/pool-metrics.jsonl','pool/pool-metrics.jsonl.summary.json')};workload=@{vu=200;durationSeconds=105;intervalSeconds=1;aiDelayMs=2000;storageDelayMs=100;timeoutMs=10000;drainSeconds=30;appCpu=2;appMemory='3GiB';poolMax=400;pending=800;dbPool=10;admission=320};orderedSteps=@('fresh recreate','warm-up','collector start','core','collector completion','collector validation','artifact copy','finalization')};Json $manifest $plan;if($ExecutionMode-eq'PLAN'){"PLAN READY: $id";exit 0};if($RunDate -notmatch '^\d{8}$'){throw 'EXECUTE requires -RunDate YYYYMMDD'};Gate;New-Item -ItemType Directory -Force -Path $target|Out-Null;New-Item -ItemType File -Path (Join-Path $target 'RUNNING')|Out-Null
$previous=@{};foreach($e in @{DOENG_EXP119_APP_IMAGE=$app;DOENG_EXP119_MOCK_IMAGE=$mock;DOENG_EXTERNAL_LEASING_STRATEGY=$policy.leasingStrategy;DOENG_EXTERNAL_MAX_IDLE_TIME_MS=$policy.maxIdleTimeMs;DOENG_EXTERNAL_EVICTION_INTERVAL_MS=$policy.evictionIntervalMs}.GetEnumerator()){$previous[$e.Key]=[Environment]::GetEnvironmentVariable($e.Key,'Process');[Environment]::SetEnvironmentVariable($e.Key,$e.Value,'Process')};$steps=[System.Collections.Generic.List[string]]::new();$failure=$null;$cleanup='NOT_ATTEMPTED';$collector=$null
try {docker compose -p $project @args up -d --force-recreate --no-build mariadb experiment-mock flux-corrected;if($LASTEXITCODE){throw 'Fresh recreate failed'};$steps.Add('fresh recreate');& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'run-isolated-vu-success-smoke.ps1') -RunId $warm -Implementation "exp120-$Condition-warmup" -TargetUrl http://127.0.0.1:8001/game/face -ServerService flux-corrected -ComposeProject $project -ComposeFiles ($files -join ',') -ActiveMissions 20 -AiDelayMs 2000 -StorageDelayMs 100 -IntervalMs 1000 -DurationMs 5000 -RequestTimeoutMs 10000 -TargetP95Ms 10000 -EnableObservability 0 -OutcomeMode controlled-admission -AccountingMode corrected -DrainObservationSeconds 10;if($LASTEXITCODE){throw 'Warm-up failed'};$steps.Add('warm-up');New-Item -ItemType Directory -Force -Path $staging|Out-Null;$collector=Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $PSScriptRoot 'collect-diagnostic-pool.ps1'),'-ManagementUrl','http://127.0.0.1:9001','-OutputPath',(Join-Path $staging 'pool-metrics.jsonl'),'-DurationSeconds','150','-IntervalMilliseconds','1000') -WorkingDirectory $root -WindowStyle Hidden -PassThru;$steps.Add('collector start');& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'run-isolated-vu-success-smoke.ps1') -RunId $id -Implementation "exp120-$Condition-core" -TargetUrl http://127.0.0.1:8001/game/face -ServerService flux-corrected -ComposeProject $project -ComposeFiles ($files -join ',') -ActiveMissions 200 -InitialActiveUsers 200 -ActivationStepUsers 200 -AiDelayMs 2000 -StorageDelayMs 100 -IntervalMs 1000 -DurationMs 105000 -RequestTimeoutMs 10000 -TargetP95Ms 10000 -EnableObservability 1 -EnableJfr 0 -EnableContainerMonitor 1 -SkipApplicationSnapshot 1 -SkipMockMetrics 1 -OutcomeMode controlled-admission -AccountingMode corrected -DrainObservationSeconds 30;if($LASTEXITCODE){throw 'Core process failed'};$steps.Add('core');$container=(docker compose -p $project @args ps -q flux-corrected).Trim();if([string]::IsNullOrWhiteSpace($container)){throw 'Application container unavailable for existing log artifact capture'};docker logs --timestamps $container 2>&1|ForEach-Object{$_.ToString()}|Set-Content (Join-Path $legacy 'application.log') -Encoding UTF8;if($LASTEXITCODE){throw 'Application log capture failed'};$collector.WaitForExit();if($collector.ExitCode-ne0){throw 'Pool collector process failed'};$steps.Add('collector completion');Copy-Exp120Artifacts $legacy $staging $target;$steps.Add('artifact copy');New-Item -ItemType Directory -Force -Path (Join-Path $target 'provenance')|Out-Null;Json ([ordered]@{runId=$id;applicationImageId=$appId;mockImageTag=$mock;mockImageId=$mockId;mockImageBindingMode='EXPLICIT_FROZEN_TAG';policy=$policy}) (Join-Path $target 'provenance\runtime-provenance.json')}catch{$failure=$_}finally{try{docker compose -p $project @args down --remove-orphans|Out-Null;if($LASTEXITCODE){throw 'Cleanup failed'};$cleanup='COMPLETED'}catch{$cleanup="FAILED: $($_.Exception.Message)";if($null-eq$failure){$failure=$_}};foreach($e in $previous.GetEnumerator()){[Environment]::SetEnvironmentVariable($e.Key,$e.Value,'Process')}}
if($null-eq$failure){try{Json ([ordered]@{runId=$id;executionStatus='COMPLETED';artifactValidation='PASSED';completedSteps=@($steps);cleanupResult=$cleanup}) (Join-Path $target 'execution-summary.json');Assert-Exp120Artifacts $target;Set-Exp120Terminal $target 'COMPLETED'}catch{$failure=$_}}
if($null-ne$failure){Json ([ordered]@{runId=$id;condition=$Condition;failedStep=if($steps.Count){$steps[$steps.Count-1]}else{'pre-run'};errorType=$failure.Exception.GetType().FullName;errorMessage=$failure.Exception.Message;completedSteps=@($steps);cleanupResult=$cleanup;timestamp=(Get-Date).ToUniversalTime().ToString('o')}) (Join-Path $target 'failure-summary.json');Set-Exp120Terminal $target 'EXECUTION_FAILED';throw $failure}
